import {CARDS,ROLES,stageOffers} from './engine.js?v=20261112a';
import {KEEPSAKES} from './content/keepsakes.js?v=20261112a';
import {ENEMIES} from './content/enemies.js?v=20261112a';
import {unlocks} from './progression.js?v=20261112a';
import {noxChapter} from './campaign-story.js?v=20261112a';
import {tokenMarkup,itemMarkup} from './token-art.js?v=20261112a';
import {abilityEffectsMarkup} from './ability-guide.js?v=20261112a';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
export function keepsakeChoiceMarkup(s){return `<p class="modal-sub">기억 유물은 들고 있는 동안 원정 규칙을 바꿉니다. 시작 유물을 포함해 최대3개를 간직합니다.</p><div class="campaign-choices">${s.pending.options.map(id=>`<button data-act="keepsake" data-id="${id}">${itemMarkup(KEEPSAKES[id].art,64)}<strong>${KEEPSAKES[id].name}</strong><p>${KEEPSAKES[id].text}</p><small>${KEEPSAKES[id].lore}</small></button>`).join('')}</div><div class="modal-actions"><button data-act="skipKeepsake" class="subtle-button">이 기억은 남겨 두기</button></div>`;}
export function endingChoiceMarkup(){return `<p class="first-help-text">유물 안에서 아직 돌아오지 못한 이름들이 울립니다. 어떤 약속을 가지고 지상으로 돌아갈까요?</p><div class="campaign-choices"><button data-act="ending" data-id="seal">${itemMarkup('seal',72)}<strong>문을 닫아 고요를 지키기</strong><p>은신 +3 · 회수 소리5 · 귀환 제한10턴</p><small>잠들고 싶었던 기억들에게 고요를 약속합니다.</small></button><button data-act="ending" data-id="remember">${itemMarkup('lantern',72)}<strong>이름을 함께 데려가기</strong><p>방어 +3 · 회수 소리8 · 귀환 제한10턴</p><small>잊힌 이름들을 금고 밖에서 다시 부르기로 합니다.</small></button></div>`;}
export function artifactShopMarkup(s){
 if(s.campaignVersion!==1)return '';
 const k=s.rooms[s.pos].stage;if(k>2||s.stagePrepared[k]===null)return '';
 return `<details class="artifact-shop"><summary>기억 유물 교역 · 금화7 · 이 정비소1회</summary><p>소지 ${s.keepsakes.length}/3. ${s.keepsakes.map(id=>KEEPSAKES[id].name).join(' · ')}</p><div class="campaign-choices">${s.artifactStock[k].map((id,i)=>`<button data-act="buyKeepsake" data-index="${i}" ${s.gold<7||s.keepsakeTrades[k]||s.keepsakes.length>=3||s.keepsakes.includes(id)?'disabled':''}>${itemMarkup(KEEPSAKES[id].art,48)}<strong>${KEEPSAKES[id].name}</strong><p>${KEEPSAKES[id].text}</p><small>금화7</small></button>`).join('')}</div></details>`;
}
export function progressMarkup(profile,state){const u=unlocks(profile),[title,line]=noxChapter(profile);return `<div class="progress-summary">${itemMarkup('lantern',72)}<div><strong>깜부기의 불씨 ${profile.embers}</strong><p>원정 ${profile.runs} · 귀환 ${profile.wins} · 해금한 메달 ${24+u.cards.length}/60 · 기억 유물 ${u.keepsakes.length}/16</p></div></div><blockquote><b>녹스 · ${title}</b><p>${line}</p></blockquote><p>다음 기록은 패배해도 이어집니다. 해금은 선택지를 넓히며 전투 수치를 영구적으로 더하지 않습니다.</p><label class="heat-choice">금고 기억 단계 <select id="heatLevel">${Array.from({length:profile.maxHeat+1},(_,i)=>`<option value="${i}" ${i===profile.heat?'selected':''}>${i} / 10</option>`).join('')}</select></label><p>높은 단계에서는 적이 강해지고 메아리가 오래 남습니다. 다음 새 원정에 적용합니다.</p><button class="keyword-button" data-act="saveHeat">단계 선택 저장</button><h3>간직한 기억 유물</h3><div class="artifact-grid">${Object.entries(KEEPSAKES).map(([id,k])=>`<article class="${u.keepsakes.includes(id)?'':'locked'}">${itemMarkup(k.art,40)}<strong>${u.keepsakes.includes(id)?k.name:'아직 잠든 기억'}</strong><p>${u.keepsakes.includes(id)?k.text:'원정을 이어 가면 이 기억이 풀에 합류합니다.'}</p></article>`).join('')}</div><h3>돌아온 이야기</h3><p>${profile.endings.includes('seal')?'✓ 고요의 약속':'○ 고요의 약속'} · ${profile.endings.includes('remember')?'✓ 이름을 데려온 약속':'○ 이름을 데려온 약속'}</p><div class="progress-history">${profile.history.map(h=>`<p>${h.won?'귀환':'등불을 이어감'} · ${ROLES[h.role]?.name||h.role} · 기억 단계${h.heat} · ${h.turn}턴</p>`).join('')||'<p>아직 원정의 결말이 없습니다.</p>'}</div>`;}
export function contentCodexMarkup(){return `<h3>기억 메달 60종</h3><div class="artifact-grid">${Object.entries(CARDS).map(([id,c])=>`<article>${tokenMarkup(id,{size:46})}<strong>${c.name}</strong>${abilityEffectsMarkup(id)}<p>${c.text}</p></article>`).join('')}</div><h3>금고의 존재 10종</h3><div class="artifact-grid">${Object.values(ENEMIES).map(e=>`<article><strong>${e.name}</strong><p>${e.text}</p></article>`).join('')}</div>`;}
export function feedbackMarkup(record={}){return `<p class="first-help-text">기록은 이 브라우저에만 남습니다. 서버로 전송하지 않습니다. 동의한 테스트 기록을 직접 내보내 개발자에게 전달할 수 있습니다.</p><label><input type="checkbox" id="feedbackConsent" ${record.consent?'checked':''}> 익명 행동 기록을 이 기기에 저장하는 데 동의합니다.</label><label>가장 헷갈린 순간<textarea id="feedbackText" maxlength="1000" placeholder="예: 새 메달이 언제 다시 나오는지"></textarea></label><label>화면 수치 없이 소리만으로 위험 변화를 알았나요?<select id="audioFeedback"><option value="unknown">소리를 평가하지 못함</option><option value="yes">알 수 있었음</option><option value="no">구분하기 어려웠음</option></select></label><div class="modal-actions"><button data-act="recordFeedback" class="large-button">이 기기에 의견 저장</button><button data-act="exportFeedback" class="keyword-button">테스트 기록 내보내기</button></div>`;}

export function carriedKeepsakesMarkup(s){if(s.campaignVersion!==1)return '';return `<details class="carried-keepsakes"><summary>지닌 기억 유물 ${s.keepsakes.length}/3 · 지속 효과 보기</summary>${s.keepsakes.map(id=>`<article>${itemMarkup(KEEPSAKES[id].art,40)}<div><strong>${KEEPSAKES[id].name}</strong><p>${KEEPSAKES[id].text}</p></div></article>`).join('')}</details>`;}
